 boolean openFolderRow(android.view.View view,String title){
  if(view instanceof android.widget.CheckBox&&((android.widget.CheckBox)view).getText().toString().startsWith(title+"\n")){
   android.view.ViewGroup row=(android.view.ViewGroup)view.getParent();for(int i=0;i<row.getChildCount();i++)if(row.getChildAt(i) instanceof android.widget.Button&&"Открыть".contentEquals(((android.widget.Button)row.getChildAt(i)).getText())){row.getChildAt(i).performClick();return true;}
  }
  if(view instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)view;for(int i=0;i<g.getChildCount();i++)if(openFolderRow(g.getChildAt(i),title))return true;}return false;
 }
