 android.view.View contextRowView(android.view.View view,String title,boolean openButton){
  if(view instanceof android.widget.CheckBox&&((android.widget.CheckBox)view).getText().toString().startsWith(title+"\n")){
   if(!openButton)return view;android.view.ViewGroup line=(android.view.ViewGroup)view.getParent();for(int i=0;i<line.getChildCount();i++){android.view.View child=line.getChildAt(i);if(child instanceof android.widget.Button&&((android.widget.Button)child).getText().toString().equals("Открыть"))return child;}return null;
  }
  if(view instanceof android.view.ViewGroup){android.view.ViewGroup group=(android.view.ViewGroup)view;for(int i=0;i<group.getChildCount();i++){android.view.View found=contextRowView(group.getChildAt(i),title,openButton);if(found!=null)return found;}}return null;
 }
 void longManagerRow(final String title,final boolean openButton)throws Exception{
  waitForIdleSync();final int[] xy=new int[2];final boolean[] ready={false};runOnMainSync(new Runnable(){public void run(){android.view.View target=contextRowView(activity.getWindow().getDecorView(),title,openButton);if(target!=null&&target.isShown()&&target.isEnabled()&&target.getWidth()>0&&target.getHeight()>0){target.getLocationOnScreen(xy);xy[0]+=target.getWidth()/2;xy[1]+=target.getHeight()/2;ready[0]=true;}}});check(ready[0],"long-press target found "+title);
  long time=android.os.SystemClock.uptimeMillis();android.view.MotionEvent down=android.view.MotionEvent.obtain(time,time,android.view.MotionEvent.ACTION_DOWN,xy[0],xy[1],0);down.setSource(android.view.InputDevice.SOURCE_TOUCHSCREEN);check(getUiAutomation().injectInputEvent(down,true),"real context DOWN injected");down.recycle();Thread.sleep(android.view.ViewConfiguration.getLongPressTimeout()+300);
  android.view.MotionEvent up=android.view.MotionEvent.obtain(time,android.os.SystemClock.uptimeMillis(),android.view.MotionEvent.ACTION_UP,xy[0],xy[1],0);up.setSource(android.view.InputDevice.SOURCE_TOUCHSCREEN);check(getUiAutomation().injectInputEvent(up,true),"real context UP injected");up.recycle();waitText("Действия с выбором");
 }
